def place_existing_requests(apps, schema_editor):
    """Put every existing case on the stage its department and history show. Safe to rerun."""
    Request = apps.get_model('requests', 'Request')
    stopped = ('closed', 'cancelled')

    def put(stage, rows):
        ids = list(rows.values_list('pk', flat=True))
        for start in range(0, len(ids), 500):
            Request.objects.filter(pk__in=ids[start:start + 500]).update(funnel_stage=stage)

    put('lead', Request.objects.filter(department='marketing'))
    put('qualification', Request.objects.filter(department='sales').exclude(sales_phase='negotiation'))
    put('first_contract', Request.objects.filter(department='sales', sales_phase='negotiation'))
    put('initial_design', Request.objects.filter(department='technical'))
    done = Request.objects.filter(department='done')
    won = done.exclude(status__in=stopped)
    put('execution', won)
    put('operation', won.filter(plant__inverters__isnull=False).distinct())
    # A lost case keeps the furthest stage its history proves it reached.
    lost = done.filter(status__in=stopped)
    put('lead', lost)
    put('qualification', lost.filter(marketing_reviewed_at__isnull=False))
    put('initial_design', lost.filter(triaged_at__isnull=False))
    put('first_contract', lost.filter(technical_completed_at__isnull=False))


